      "讯息 › 朋友圈 › 周常朋友圈 › 8.23-8.29 凉面\n\n白起 ：自己拌的凉面的确更好吃。\n[玩家姓名] ：可是这个有一座小山高的凉面是怎么回事！\n白起 回复 [玩家姓名] ： ……听说你没吃饭，所以面煮得有点多。\n[玩家姓名] ：这么好吃的食物，要是四季都有就好了！\n白起 回复 [玩家姓名] ： 想吃的时候告诉我，我这里无限供应。\n[玩家姓名] ：你学得也太快了！比我做得还好！\n白起 回复 [玩家姓名] ： 是你教得好。"
