      "杂篇 › 活动剧情 › 拿卡剧情 › sr › sr-恋恋炽鸣\n\n他大概是在队友吃饭的间隙里给我打的电话，隐隐有嘈杂的人声传来。\n“猪脚米线一碗——”\n白起大概向前走了几步，嘈杂声渐渐消失。\n白起： 我不累，这个任务算是比较轻松的。\n[玩家姓名]： 那你什么时候回来？\n我按捺住想告诉他我已经和他在同一座城市的心情，想最后再确认一遍他的时间。\n但白起停顿了一下，大概听出了我话里的期待，他没有直接回答。\n白起： 不用担心我回去的时间。\n白起： 我保证，你的所有期待都不会落空。"
