      "讯息 › 电话 › 羁绊解锁 › 0103 垃圾食品\n\n白起： 听韩野说，你最近天天加班，午饭还都在吃快餐？\n[玩家姓名] ：……他怎么天天打小报告！\n[玩家姓名] ：你听我解释，这汉堡里面夹着芝士片，煎烤好的鸡肉，还有绿色蔬菜……所谓荤素俱全，包含着丰富的蛋白质、维生素与加班必备的碳水。配上无糖冰可乐还有薯条，可以为痛苦的加班生活增添一些快乐。\n白起： 嗯，继续说。\n[玩家姓名] ：……",
      "杂篇 › 活动剧情 › 周年活动 › 六周年-佳岁与共 › 恋爱环游记 › 千麓雪山\n\n[玩家姓名]： 你之前说来过这附近，原来是进山里了吗？\n白起： 一开始我们是埋伏在镇里的，后来线人走漏了消息，目标就藏进了山。当时也差不多是这个时候吧，对方熟悉地形，Evol又能控制一定范围内的温度，很占优势。我们很难掌握到行踪，所以在这几座山待了一段日子。\n[玩家姓名]： 只是“待了”吗？\n白起： ……在雪地里躺了好几个晚上？\n[玩家姓名]： 还有呢。\n白起： 咳……当时物资有点断了，没办法及时获得补给，取暖设备和食物都有些匮乏。不过后来很顺利，抓到人了。\n他一副云淡风轻的样子，我却下意识地握紧了他的手。\n……\n白起： 是，后来我们就以这次行动为典型案例，尽量避免类似的情况再次发生。那次行动没有一个队员受重伤。我回来之后你也仔仔细细检查过，只有几道很轻的擦伤。我们一起睡到第二天中午才醒，出门去吃了一家很好的餐厅。\n白起： 你还说那家店的苹果派和汉堡排特别好吃。",
