      "约会 › 约会剧情 › er › 观赛之约\n\n旁边两桌的人已经飞快拼成了一桌，听到他们倒起了苦水，白起的表情也变得有些微妙。他像是回想起了什么不好的回忆般，有些欲言又止地眨了两下眼睛。\n白起： 这个双椒牛肉不错哈。\n我扑哧笑了起来，朝他努努嘴。\n[玩家姓名]： 嗯，是挺不错的……你不加入？\n白起： 加入什么？\n[玩家姓名]： 当然是隔壁的A队粉丝伤心交流会啊。\n白起： 不去。我和他们不一样，我只是欣赏A队的打法风格，并不算他们的狂热粉丝。\n[玩家姓名]： 嗯嗯。\n我眨了眨眼，决定不戳穿他曾经在A队还没淘汰时和我商量过要不要带篮球来签名的事。\n白起说着又沥了沥牛肉上的花椒，夹到了我的碗里。\n白起： 再说了，就算要交流比赛，我也只和你交流。比如这次我早就预感A队可能会输，他们打得太松懈轻敌了。"
