      "约会 › 约会剧情 › er › 夺冠之约\n\n几日的不规律作息让我有些精神不佳，偷偷买黑咖啡的时候，被白起捉了现行，并一把抱起……\n\n我沿着赛道走向自动贩卖机，想着先买瓶咖啡饱腹，再去找白起。\n谁知刚喝了两口，或许是没吃早饭的原因，大脑突然一阵眩晕。\n等我缓过神的时候，已经被一股熟悉的力量抱起放上了长椅。对上白起略显紧张的目光，我连忙扯起嘴角笑了笑。\n[玩家姓名]： 白起，我正找你呢，原来你在这里呀。\n他没有说话，抬手轻轻擦去我额前的虚汗。接着，一阵轻风温柔地环绕着我，温热又安心。"
