      "约会 › 约会剧情 › er › 悸动之约\n\n白起仍然站在公交站台下没有离开，他的目光似乎穿过了车窗，落在我身上。\n我望着窗外那些闪烁的灯光，和飞驰而过的汽车，心里忽然冒出一个奇怪却又执着的念头。\n这一次，脚下的路不会走完，路的尽头，也通往许多个明天。\n但我转过身背对他时，心中还是会涌起强烈的不舍。\n我有很多话想听他说。\n大雨那天的校服外套是不是他的，琴房里的草莓牛奶是不是他放的。\n那些青涩又真诚的秘密，是不是都被他小心又笨拙地藏着。\n脚步不受控制地往回走，我在关门之前跑回了车门前。\n透过这道窄窄的门，我看见那个少年仍站在站台前。",
      "主线 › 第一季 › vol.7-命运回响 › 漂浮记忆 › 31-12\n\n琴房对于高中的我来说是除了班级最亲切的地方，我看着熟悉的摆设，心中涌起一股怀旧之情。白起也顺着我的视线环顾了一圈，轻轻地“嗯”了一声。\n[玩家姓名]： 不过说起来，当时这里还发生了不少奇怪的事……\n白起： 什么奇怪的事？\n[玩家姓名]： 比如说忽然多出来的草莓牛奶、冬天的热饮……当初朋友吓唬我说这是恋语高中十大怪谈之一，吓了我一跳。\n我掰着手指一件件回忆高中时的趣事，白起的脸色却变得有些不太好看。\n白起： 你觉得是鬼故事？\n[玩家姓名]： 当然不会，我知道这是他们开玩笑的。而且怎么会有这么好心的“鬼”啊，大概是哪个热心的同学吧。\n白起的脸色稍微缓和了些，点点头，但仍是一副欲言又止的样子。"
