      "约会 › 约会剧情 › ssr › 培训之约\n\n白起： 我早就不是高中生了。\n他的气息蹭过我的耳垂，落入脖颈。\n白起： 而且，跟你一起好好听课会更帅一点。\n[玩家姓名]： 这个学习动机是不是有点不“单纯”呀学长？\n白起： 不过学归学，到最后还是需要你帮我补补课。\n他说着，往我这边推来一瓶豆奶，又不知从哪里摸出几颗巧克力和两包青豌豆。\n白起： 学费。\n[玩家姓名]： 既然你如此有诚意，那我想想哦……\n我拆开豆奶，把椅子挪得离他更近了一些，看向屏幕上他的课件。\n[玩家姓名]： 先把课件排版改了吧？重点这样标出来，然后……\n白起一边看我改动，一边把笔记本摊开到新一页开始记笔记。",
