      "约会 › 约会剧情 › ssr › 彻夜之约\n\n此刻的摊位静悄悄的，我好奇地四处打量，白起则翻看起一旁的棉花糖机操作说明书。\n白起： ……“无需工作人员陪同，可自行操作。”\n白起： 懂了。\n……\n我话音还没落，白起已经按下了某个按钮。\n棉花糖机发出轻快的嗡鸣，一旁的彩灯也闪烁起来——还没有到营业时间的机器就这么被白起唤醒了。\n……\n我凑到白起身边，看着在他动作下逐渐有了雏形的棉花糖。\n[玩家姓名]： 还挺有模有样的！总觉得你好像不知不觉间为了我增加了不少新技能，现在连做棉花糖的技能点都达成了！\n白起： 确实。\n白起一边继续着手上的动作，让形状规整的棉花糖越卷越大，一边顺着我的话轻飘飘地接了一句。\n白起： 毕竟我爱你啊。",
