      "约会 › 约会剧情 › sr › 闻香之约\n\n街角的奶茶店并不大，或许是身为香料小镇的缘故，这里的奶茶品类似乎也有所不同。\n店员： 两位喝点什么？这里推荐本地产的雪山饮品，口感微苦但是很暖身子。\n店员： 如果喝不习惯的话，旁边还有砂糖可以自行取用。\n原本我的视线还在被那些包装可爱的奶茶所吸引，但听完店员的推荐，让我不禁有些跃跃欲试。"
