      "杂篇 › 活动剧情 › 拿卡剧情 › ssr › ssr-季夏信风\n\n[玩家姓名]： 没想到许愿池旁边居然藏着这么好吃的冰淇淋小铺！\n白起： 嗯，栗子口味的很好吃。\n[玩家姓名]： 那我们许个愿好啦，希望明天我们也能吃到好吃的栗子甜品。\n白起： 我们住处旁边的一家店铺，栗子冰糕做得很好。\n[玩家姓名]： 居然还有这种事！我都没注意。\n白起： 毕竟那家店铺很小，我也是无意中看旅游手册发现的。\n[玩家姓名]： 早知道就直接把硬币给你了……总觉得浪费了一个愿望。\n白起： 我还有硬币，再许一个？",
