      "约会 › 约会剧情 › ssr › 标记之约\n\n绿荫交错的顶棚下，白起在小黑板上写着菜单。他身边站着两只“小狼”，其中一只嘴里还“叼”着一张卡片。或许是担心小朋友们害怕，这两只小狼脸被做得圆嘟嘟的，威猛中夹杂着可爱。和煦的阳光穿过顶棚垂下的绿植藤蔓，在白起身上晕开一片斑斓，静谧又温暖。\n白起： 海盐白桃冰冰茶，荔枝酸奶千层蛋糕……\n白起工整地将菜单写好，又在旁边有些笨拙地画了一只小兔子。只是这个兔子的脸有些过于圆润，看上去憨憨的，我不禁笑出声，走了过去。\n[玩家姓名]： 没想到我才离开这么一会，你就找到了两个小“帮手”。\n见到我，他的眼睛一亮，身后的大尾巴也不自觉地摇摆了两下。"
